#!/usr/bin/env python3
"""Deterministic static site. All scientific numbers come from committed receipts."""
from pathlib import Path
import json
import html
import shutil
ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / 'docs'
def load(name): return json.loads((ROOT/'evidence'/name).read_text())
def esc(x): return html.escape(str(x), quote=True)
def link(url, label, cls=''):
    download = ' download' if not url.startswith('http') and url.endswith(('.tif', '.zip')) else ''
    return f'<a class="{cls}" href="{esc(url)}"{download}>{esc(label)}</a>'
def badge(text, good=False): return f'<span class="badge {"good" if good else "bad"}">{esc(text)}</span>'
def metric(s):
    return f'<strong>{s["dti"]:.5f}</strong><span class="interval">95% CI [{s["ci95"][0]:.5f}, {s["ci95"][1]:.5f}]</span>'

def shell(title, body, active='summary'):
    nav = [('experiment-index.html','summary','Experiment overview'),('submission-guide.html','guide','How to submit'),('hypotheses.html','science','Research'),('sources.html','sources','Sources & limits')]
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>{esc(title)} · GEMS discovery lab</title><meta name="description" content="Evidence-led fault discovery. Automated GeoTIFF validation, spatial holdout results, and transparent submission eligibility."><link rel="stylesheet" href="assets/site.css"><script defer src="assets/site.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><a class="brand" href="index.html"><span class="mark">G</span><span>GEMS<span class="brand-sub">DISCOVERY LAB</span></span></a><nav aria-label="Main navigation">{''.join(f'<a href="{u}" {"aria-current=page" if a==active else ""}>{t}</a>' for u,a,t in nav)}</nav><a class="repo" href="https://github.com/karagemop466-tech/GEMSDOEkarage2">Repository ↗</a></header><main id="main">{body}</main><footer><div><strong>Evidence over confidence.</strong><p>Maximize P(Win). Own the outcome. Protect scarce submission slots.</p></div><div>Snapshot: 27 Oct 2026 · UTC<br>Geological hypotheses are not verified geothermal discoveries.</div></footer></body></html>'''

METHODS = {
 'GEMSDOE24':'Dense dotted H19-5 lineage, nominal d1.5 spacing. A historical baseline, not a new eligible file.',
 'GEMSDOE25':'More widely spaced D2.8 emission. Decoded dots are exactly identical to the GEMSDOE30 historical mask.',
 'GEMSDOE27':'Topographic gap closure on the d1.5 parent. The supplied historical report does not establish improvement over its parent.',
 'GEMSDOE28':'Highest value in the supplied site list belongs to H36-1 rung30 blind R1. Other listed variants are not independently better; no receipts are available.',
 'GEMSDOE30':'Poisson/off-catalogue D2.8 emission. Different packaging does not make its dots different from GEMSDOE25.',
 'GEMSDOE31':'B1 / solo D2.8 pruning: the decoded mask equals D2.8 with distances of at most one pixel from known traces removed.',
 'GEMSDOE32':'B2 / solo D2.8 pruning: the decoded mask equals D2.8 with distances of at most two pixels from known traces removed. Highest unverified user report in the nine-site list.',
 'GEMSDOE33':'Analog tip/stepover additions. Its title is not evidence of new fault detections; the historical mask remains too close to the common family under the requested gate.',
 'GEMSDOE36':'The entire GEMSDOE32 B2 set plus 1,200 additional positive pixels. This is a measured mask relationship, not independent verification of the PINN interpretation.'
}

def main():
    card, ho, src, forensic, reg = [load(p) for p in ('run_card.json','holdout.json','sources.json','champion_forensics.json','surface_registry.json')]
    # The earlier experiment audit used NaN-padded siblings for five claims.
    # Use the newer, independently pinned audit of the exact named claim files
    # for the current scorecard and per-site pages; preserve the earlier JSON.
    current = json.loads((DOCS/'data/focus_audit.json').read_text())
    (DOCS/'evidence').mkdir(exist_ok=True)
    # Field Notes publishes its own distinct follow-on receipts under
    # docs/field-notes/data; do not duplicate or confuse them with H1's card.
    for p in (ROOT/'evidence').glob('*.json'):
        if p.name not in {'geometry-audit.json', 'preparation.json', 'run-card.json'}:
            shutil.copyfile(p, DOCS/'evidence'/p.name)
    shutil.copyfile(ROOT/'knowledge/hypotheses.md', DOCS/'evidence/hypotheses.md')
    shutil.copyfile(ROOT/'knowledge/champion_explanation.md', DOCS/'evidence/champion_explanation.md')
    shutil.copyfile(ROOT/'evidence/review.md', DOCS/'evidence/review.md')
    shutil.copyfile(ROOT/'registry/focus_registry_manifest.json', DOCS/'evidence/focus_registry_manifest.json')
    candidate = ho['scores']['candidate']
    best = ho['scores'][ho['best_comparable_control']]
    version = esc(candidate['evaluator_version'])
    tif = card['raster'].removeprefix('docs/')
    rows = []
    ordered = sorted(current['sites'],key=lambda r:-r['reported_score'])
    for r in ordered:
        site=r['site']
        rows.append(f'''<tr><td><a class="site-name" href="sites/{site}.html">{site} ↗</a><span class="muted">{r['positive_pixels']:,} positive pixels</span></td><td><code class="file-name">{esc(r['filename'])}</code></td><td><strong>{r['reported_score']:.4f}</strong><span class="muted">Unverified user report</span></td><td>Not estimable<span class="muted">No receipt or valid OOF reconstruction</span></td><td>{badge('NOT lane-unique')}<span class="muted">Do not resubmit</span></td></tr>''')
    controls=''.join(f'<div class="comparison"><div><span>{esc(n.replace("_", " "))}</span>{metric(ho["scores"][n])}</div><div class="track"><span style="width:{ho["scores"][n]["dti"]/.08*100:.2f}%"></span></div></div>' for n in ('candidate',ho['best_comparable_control']))
    body=f'''<div class="eyebrow">FIELDNOTES / EXPERIMENT 001 <span>27 OCT 2026</span></div>
<section class="hero"><div><div class="kicker"><span class="status-dot"></span> NEGATIVE RESULT · NO SLOT USED</div><h1>A clear decision.<br>Not another guess.</h1><p class="lead">One new geological hypothesis. Spatially withheld faults. A transparent stop when the evidence did not support submission.</p><div class="actions"><button class="button primary" disabled>No approved submission TIF</button>{link('#downloads','View research download ↓','button secondary')}</div><p class="small">No file in this release is cleared for the competition. Format-valid ≠ unique ≠ high-scoring.</p></div><aside class="decision"><span class="eyebrow">AUTOMATED RELEASE GATES</span><h2>Do not submit.</h2><p>The new surface failed performance and registry checks. No final dot placement was performed.</p><div class="gate"><span>01 · Mirror-only format check</span>{badge('LOCAL ONLY',True)}</div><div class="gate"><span>02 · Holdout improvement</span>{badge('FAIL')}</div><div class="gate"><span>03 · Registry uniqueness</span>{badge('STOP')}</div><a href="evidence/run_card.json">Open machine-readable run card ↗</a></aside></section>
<div class="stat-grid"><article><span>HOLDOUT-DTI / NEW SURFACE</span>{metric(candidate)}<p>{candidate['withheld_positive_pixels']:,} withheld positive pixels · {version}</p></article><article><span>REGISTRY / SURFACE STOP</span><strong>100% overlap</strong><p>Directional support within 3 px of a registry lattice. Limit: &gt;70%. {reg['checked']} of {reg['expected']} compared before mandatory stop.</p></article><article><span>AUTOMATED FORMAT VALIDATION</span><strong>Passed, not promoted</strong><p>Single band · finite [0,1] · matching mirrored CRS, shape and transform. Exterior null policy and portal acceptance remain unverified.</p></article></div>
<section class="section"><div class="section-head"><div><span class="eyebrow">THE EXECUTIVE READOUT</span><h2>What changed in the historical best?</h2></div>{link('evidence/champion_forensics.json','Inspect pixel-level evidence ↗','text-link')}</div><div class="two-col"><article class="panel"><h3>Pruning, not a new detector.</h3><p>GEMSDOE32’s historical B2 file is exactly the D2.8 mask with predictions within 200 m of known traces removed. The audit measured <strong>{forensic['removed_d28_to_b2']:,} removed pixels</strong>; {forensic['removed_b1_to_b2']:,} were removed relative to its B1 parent.</p><p>The supplied <strong>0.2778</strong> is an <strong>unverified user report</strong>, not an ORGANIZER-CONFIRMED receipt. It is the highest such report in the nine-site list, not a verified current leaderboard high.</p></article><article class="panel"><h3>Why that might help—and what it cannot prove.</h3><p>DTI balances covered withheld truth against false-positive mass. Removing low-credit predictions can improve that balance without discovering a new fault. This is a plausible explanation, not a causal finding about hidden competition labels.</p><p>GEMSDOE25 and 30 have identical decoded dots. GEMSDOE36 contains the full B2 mask plus 1,200 pixels. These are one related emission family, not independent validation of nine geological models.</p><p><a href="evidence/champion_explanation.md">Exact pruning condition and interpretation limits ↗</a></p></article></div></section>
<section class="section"><div class="section-head"><div><span class="eyebrow">NINE-SITE SUBMISSION AUDIT</span><h2>Know exactly what you are downloading.</h2></div><span class="quiet-tag">Immutable revisions · verified raster bytes</span></div><p>Highest <em>user-reported historical</em> file per focus site, ranked by that report. No historical value is treated as a score estimate or organizer receipt. The byte-audited filenames match the published historical claims; earlier NaN-padded siblings are preserved only as a separate audit. Each site has its own executive summary. <strong>None is recommended for resubmission.</strong></p><div class="table-wrap"><table><caption>Historical files, estimate availability, and uniqueness eligibility</caption><thead><tr><th scope="col">Source site</th><th scope="col">Exact historical filename</th><th scope="col">Historical claim</th><th scope="col">Estimated leaderboard score</th><th scope="col">Unique / submit?</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="small">“NOT lane-unique” means proximity/correlation exceeds the requested gate; it does not mean every file has identical bytes. Global uniqueness across all other sites is not certified. {link('data/focus_audit.json','Full pairwise measurements ↗')}</p></section>
<section class="section two-col"><article class="panel"><span class="eyebrow">NEW HYPOTHESIS · H1</span><h2>Signed displacement parity</h2><p>Opposing elevation and basement-depth gradients, conductivity contrast, and persistence across 200 m and 600 m smoothing scales. No catalogue-derived predictor and no reused submission dots.</p><p><strong>Named confounder:</strong> basin sedimentation plus saline groundwater. Interpolation boundaries can also mimic a structural signal.</p>{link('hypotheses.html','Read all four preregistered hypotheses →')}</article><article class="panel"><span class="eyebrow">PAIRED SPATIAL HOLDOUT · NOT A LEADERBOARD ESTIMATE</span><h3>The new surface did not beat its controls.</h3>{controls}<p class="small">HOLDOUT-DTI · {version} · {candidate['withheld_positive_pixels']:,} withheld positives. 20 km cluster-bootstrap 95% CIs, conditional on the fixed folds and mirrored catalogue. Controls are not a reconstruction of the historical champion.</p><p class="small">All individual-feature AUC canaries passed the 0.90 threshold. A pass is not proof of absence of leakage. {link('evidence/holdout.json','Every feature and fold ↗')}</p></article></section>
<section class="download-panel" id="downloads"><div><span class="eyebrow">DOWNLOADS / RESEARCH ONLY</span><h2>A new raster. An honest negative result.</h2><p>The physical surface was calculated from restored feature layers—not copied from an old submission. It passes the local format validator but <strong>fails the required uniqueness gate</strong>. It is not a final dotted submission.</p><p><code>{esc(Path(tif).name)}</code></p><div class="actions">{link(tif,'Download research TIF · DO NOT SUBMIT','button research')}{link(tif.replace('.tif','.zip'),'Single-TIF ZIP','button secondary')}{link('evidence/validator.json','Validator receipt ↗','button secondary')}</div><p class="small">SHA-256 <code class="hash">{card['raster_sha256']}</code></p></div><aside><h3>Submission note</h3><p>{esc(card['note'])}</p><p class="small">{len(card['note'])} characters · unique experiment name, not uniqueness clearance</p>{link('submission-guide.html','How release and submission work →')}</aside></section>
<section class="section"><div class="section-head"><div><span class="eyebrow">WHAT HAPPENS NEXT</span><h2>Fix the blockers, not the label.</h2></div></div><div class="next-grid"><article><span>01</span><h3>Resolve the registry stop</h3><p>The lattice covers 99.8724% of allowed cells within 3 px. This is not a proof of universal blockage. Do not change thresholds or relocate dots merely to evade it.</p></article><article><span>02</span><h3>Authenticate the comparison</h3><p>Acquire organizer input provenance, rules, quota and receipts. Rebuild the incumbent with visible-only inputs on the same folds; historical reports are not calibration data.</p></article><article><span>03</span><h3>Only then, test another lane</h3><p>The run stopped after one experiment. Deferred hypotheses are untested. The original prompt has no assigned method paragraph, so this lane is explicitly provisional.</p></article></div></section>
<section class="freshness"><div><strong>Source freshness, without false promises.</strong><p id="freshness-status" role="status">Pinned snapshot: {esc(src['retrieved_utc'])}. This is not a live leaderboard feed.</p></div><button type="button" class="button secondary" id="refresh-sources">Check public GitHub revisions ↗</button><div id="freshness-results"></div></section>'''
    (DOCS/'experiment-index.html').write_text(shell('H1 experiment overview',body))
    (DOCS/'experiment-executive-summary.html').write_text(shell('H1 experiment overview',body))
    sites_dir=DOCS/'sites';sites_dir.mkdir(exist_ok=True)
    # Nested pages use a base URL so all shared navigation and evidence links resolve.
    for r in ordered:
        site=r['site']
        overlap=r['max_other_site_overlap']
        other=r['max_overlap_reference']
        source=r['source_url']
        audit_source=next(s for s in src['sites'] if s['repo']==site)
        b=f'''<div class="eyebrow">NINE-SITE EXECUTIVE SUMMARY / {site}</div><section class="page-intro"><h1>{site}</h1><p class="lead">{esc(METHODS[site])}</p>{badge('DO NOT RESUBMIT')} <p>Best historical file according to the supplied list—not an independently verified current site champion.</p></section><div class="stat-grid"><article><span>UNVERIFIED USER REPORT · NOT A MEASURED RESULT</span><strong>{r['reported_score']:.4f}</strong><p>No organizer submission-page receipt was retrieved. This value is not a projection or an authenticated score.</p></article><article><span>ESTIMATED LEADERBOARD SCORE</span><strong>Not estimable</strong><p>A prebuilt masked submission cannot reconstruct a leakage-safe hide-and-recover estimate. No invented CI.</p></article><article><span>UNIQUENESS · RASTER MEASUREMENT</span><strong>{overlap:.2%} proximity</strong><p>Directional positive-pixel proximity within 3 px of {other}; exceeds the &gt;70% gate. Byte identity is a separate question.</p></article></div><section class="section panel"><h2>Exact historical artifact</h2><p><code>{esc(r['filename'])}</code></p><p>Positive pixels: {r['positive_pixels']:,}. Shape: {current['grid']['height']} × {current['grid']['width']}. CRS: {esc(current['grid']['crs'])}. Values inside footprint: [{r['min_in_footprint']}, {r['max_in_footprint']}]. NaNs inside footprint: {r['nan_in_footprint']}.</p><p class="small">Mirrored-footprint exterior NaN pixels: {r['nan_outside_footprint']:,}; nodata metadata: {esc(r['nodata_metadata'])}. These facts do not establish organizer format compliance. Do not infer that NaN caused the previous portal error.</p><p>SHA-256 <code class="hash">{r['sha256']}</code></p><p>Revision <code>{r['github_ref']}</code></p><div class="actions">{link(source,'Historical GitHub artifact · audit only ↗','button secondary')}{link(audit_source['source_url'],'Retrieved source page ↗','button secondary')}</div></section><section class="section two-col"><article class="panel"><h2>Submit recommendation</h2><p><strong>No.</strong> It is a historical artifact and fails the requested lane-proximity standard against another focus-site mask. Do not rename or download it as a new submission.</p><p>There is no approved new file in this release. The H1 research surface also failed; the project stopped automatically without requiring a human inspector.</p></article><article class="panel"><h2>Scope and access</h2><p>The original site was read from a pinned public GitHub revision. This session has <strong>{esc(audit_source['viewer_permission'])}</strong> permission there; it did not modify the original site. This is the local executive-summary counterpart.</p>{link('data/focus_audit.json','View all pairwise checks →')}</article></section>'''
        (sites_dir/f'{site}.html').write_text(shell(site,b).replace('<head>','<head><base href="../">',1))
    guide=f'''<div class="eyebrow">RELEASE PLAYBOOK</div><section class="page-intro"><h1>How to make a submission.<br>And when not to.</h1><p class="lead">Automated validation first. A scarce competition slot only after the scientific evidence clears every gate.</p>{badge('CURRENT RELEASE: DO NOT SUBMIT')}</section><div class="steps"><article><span>01</span><div><h2>Generate—not copy—a candidate</h2><p>Use a preregistered method inside the assigned lane. Restore pinned inputs, build the new physical surface, test every feature for leakage. Never rename, jitter or re-encode a submitted mask to claim novelty.</p><code>.venv/bin/python scripts/run_experiment.py</code></div></article><article><span>02</span><div><h2>Require a positive automated decision</h2><p>Check `run_card.json`: the verdict must be positive for selector consideration, the surface and final-dot checks must pass, and the candidate must beat a reconstructed incumbent on the same spatial holdout. Our current card says <strong>negative</strong>. Stop here.</p><p>Use whole withheld components, visible-only catalogue features, exact known-pixel masking, pooled DTI and spatial CI. A prebuilt prior file is not a valid OOF comparator.</p></div></article><article><span>03</span><div><h2>Validate the actual on-disk file</h2><p>A single-band GeoTIFF must match the submission template's CRS, shape and affine transform. The local mirror-based range preflight checks finite [0,1] values and zero exterior mass; this is not organizer format approval. The public specification calls for null/NaN outside bounds, so authenticate the official template and resolve the outside-footprint encoding before any upload. Mask known traces as required by the protocol. The writer rejects bad predictions; it does not silently clip or fill them.</p><p>The portal message “Predicted values must be in range [0, 1]” does not uniquely identify the cause. NaN, infinity, a finite nodata sentinel or a normalization bug must each be checked; this writer checks them automatically.</p><p>The ZIP contains exactly one TIFF. {link('evidence/validator.json','Current format receipt ↗')} (format passed, scientific eligibility failed).</p></div></article><article><span>04</span><div><h2>Use a separate quota-aware selector</h2><p>Promotion to a weekly slot is separate from a model run. Retrieve the current rules and actual remaining quota from the authenticated submission page; the weekly cap is not verified in this session. Never invent it. No file is currently promoted.</p></div></article><article><span>05</span><div><h2>Only with clearance: download and upload</h2><p>Download the approved <strong>.tif</strong> or its single-TIF <strong>.zip</strong>, not an HTML/JSON report. Verify SHA-256 against the approved receipt. On DrivenData choose “New submission,” select that file, and paste its distinctive short note (at most 140 characters). Capture the organizer's actual receipt and reported result as ORGANIZER-CONFIRMED; never convert a local projection into a score.</p><p>This release's TIF is a research surface only and must not be used for this step.</p>{link('https://www.drivendata.org/competitions/306/competition-doe-gems/','Official competition ↗')}</div></article></div><section class="section panel"><h2>No manual inspection workaround</h2><p>The project runs the format, holdout and registry gates itself. A negative is not waiting for a human inspector to approve an unsafe file. Missing authenticated evidence and protocol conflicts remain explicit blockers, not permission to bypass the gates.</p></section>'''
    (DOCS/'submission-guide.html').write_text(shell('Submission guide',guide,'guide'))
    science='''<div class="eyebrow">GEOLOGY / BEFORE IMPLEMENTATION</div><section class="page-intro"><h1>Four hypotheses.<br>One bounded experiment.</h1><p class="lead">Mechanisms, confounders, and ways to be wrong—not a promise of hidden faults or geothermal vents.</p></section>'''
    for n,title,layers,signature,conf,cost in [(1,'Signed downthrow parity','12 detrended elevation · 15 basement depth · 17 conductivity','Opposing signed gradients across 200/600 m scales; masked surface traces are not predictors. Could detect a buried displacement without a visible scarp.','Basin sedimentation, salinity, interpolation seams.','Low · tested; negative, stopped'),(2,'Shear-offset edge dipoles','2 reduced-to-pole magnetics · 13 isostatic gravity','Cross-strike edge-offset parity instead of coincident edge strength; buried juxtaposition need not appear in surface mapping.','Intrusive or lithologic contacts.','Medium · deferred, untested'),(3,'Conductive hinge / basement inflection','15 basement depth · 17 conductivity','Conductivity ridge transverse to a signed depth-curvature zero crossing; possible buried flexure.','Aquifer boundaries and interpolation seams.','Medium · deferred, untested'),(4,'Gravity edge without terrain expression','13 isostatic gravity · 12 detrended elevation · 19 elevation slope','Persistent gravity gradient with weak terrain expression; anti-evidence from scarps rather than the H1 topographic corroboration.','Sediment thickness changes and lithologic contacts.','Low · deferred, untested')]:
        science+=f'<article class="hypothesis panel"><span class="eyebrow">QUALITATIVE RANK {n} · NOT A SCORE PROJECTION</span><h2>H{n} · {title}</h2><p><strong>Layers:</strong> {layers}</p><p><strong>Signature and missing-fault rationale:</strong> {signature}</p><p><strong>Non-fault mimic:</strong> {conf}</p><p><strong>Cost / status:</strong> {cost}</p></article>'
    science+='''<section class="section panel"><h2>Availability and novelty limits</h2><p>All proposed inputs exist in the restored multiband mirror; none requires new external data. Original-provider units and provenance are not authenticated. The initial repository had no implementations, so these differ from the original codebase by construction. Many related methods exist upstream; this is not a global novelty claim. The inherited derived feature cache is unpublished, so selected cached source bands were reused without rebuilding the upstream stack.</p><p>The specific lane paragraph was absent from the supplied prompt. Only provisional H1 was run, and it stopped after the first experiment. Nothing is submitted automatically. No post-stop tuning was performed.</p><p>These mechanisms are geological hypotheses, not source-verified causal conclusions. The official reference addresses fault detection, not geothermal vent labeling. Structural evidence alone cannot establish heat, permeability or resource viability.</p><a href="evidence/hypotheses.md">Preregistration and full source caveats ↗</a></section>'''
    (DOCS/'hypotheses.html').write_text(shell('Hypotheses',science,'science'))
    source_rows=''.join(f'<tr><td>{esc(s["repo"])}</td><td>{link(s["source_url"],s["ref"][:12]+" ↗")}</td><td>Community source retrieved · {esc(s.get("viewer_permission","unknown"))}</td></tr>' for s in src['sites'])
    official=src['official_reference']
    sourcebody=f'''<div class="eyebrow">PROVENANCE / NO IMPLIED VERIFICATION</div><section class="page-intro"><h1>Show the evidence.<br>Name the limits.</h1><p class="lead">An immutable GitHub hash proves retrieved-byte integrity. It does not prove official origin, a leaderboard result, or scientific causality.</p></section><section class="panel"><h2>What we retrieved</h2><p>{link(official['source_url'],'Official DrivenData reference notebook ↗')} · pinned revision <code>{official['ref']}</code>. It confirms fault detection and the training-loss alpha/beta values. It does not verify the official hidden distance-tolerant scorer, current leaderboard, or quota.</p><p>Four competition-input mirror files were restored and SHA-256 verified. Labels and existing faults are byte-identical; the public catalogue is not hidden scoring truth. The sample values are never used as predictions. {link('evidence/input_restore.json','Input restoration receipt ↗')}</p><p>The shared evaluator, writer and literal uniqueness gate are unchanged upstream copies with per-file hashes. {link('evidence/sources.json','Full source and tool provenance ↗')}</p></section><section class="section"><h2>The nine site sources</h2><div class="table-wrap"><table><caption>Retrieved community sources, immutable revisions and access scope</caption><thead><tr><th>Repository</th><th>Pinned source page</th><th>Evidence / permissions</th></tr></thead><tbody>{source_rows}</tbody></table></div></section><section class="section panel"><h2>Official links not retrieved by the H1 experiment session</h2><p>The H1 experiment session could not directly retrieve these hosts. The subsequent independent review used a public web reader for several official pages; see the current research desk for dated observations. No login or file-bound receipt is implied.</p><ul>{''.join('<li>'+link(u,u)+' </li>' for u in src['official_links_not_retrieved'])}</ul></section><section class="section"><h2>Irregularities that matter</h2><div class="next-grid"><article><h3>Not the repository described</h3><p>Original checkout contained only a one-line README. No previous pipeline, cached stack, holdout best or session notes existed. Data placement is now resolved using mirrors, not authenticated organizer downloads.</p></article><article><h3>Not a live leaderboard</h3><p>The prompt cites conflicting current highs. No organizer receipt or authenticated current ranking was accessible. Historical values are segregated as unverified user claims.</p></article><article><h3>Not global uniqueness</h3><p>The registry is a path/size-filtered nine-repository snapshot. It excludes other sites, larger rasters, private history and later publications. A detected duplicate is sufficient to stop; no incomplete scan can clear uniqueness.</p></article></div></section><section class="section panel"><h2>Concurrent-session evidence retained</h2><p>Other Arena branches merged while this run was in progress. Their readiness schema, tests and source snapshots are preserved. Their earlier dashboard is clearly archived under <a href="previous-main/index.html">prior-session snapshots</a>; old summary routes redirect to the current evidence. Their reported public leaderboard observation is not independently verified by this session and is not used for calibration.</p><p><a href="evidence/selector_result.json">Combined automated selector assessment ↗</a>: negative. Missing assigned lane, compatible incumbent and final-dot coverage remain blockers, not invented inputs.</p><h2>Next-session acceptance criteria</h2><ol><li>Resolve lane assignment and literal lattice-overlap conflict without private exemptions.</li><li>Authenticate source hashes, band units, rules, current quota and receipts.</li><li>Reconstruct the incumbent on the identical visible-only buffered holdout.</li><li>Expand immutable registry coverage; then and only then consider a new experiment.</li></ol><p>Read <a href="https://github.com/karagemop466-tech/GEMSDOEkarage2/blob/main/README.md">the standing README contract</a> and <a href="evidence/review.md">three-pass review</a> before restarting. A failed gate remains failed without a substantive methodological change.</p></section>'''
    (DOCS/'sources.html').write_text(shell('Sources and limitations',sourcebody,'sources'))
    (DOCS/'evidence/freshness.json').write_text(json.dumps({'refs':{s['repo']:s['ref'] for s in src['sites']},'snapshot':src['retrieved_utc']},indent=2)+'\n')
    (DOCS/'.nojekyll').write_text('')
    print('Built executive summary, submission guide, research, provenance and nine per-site summaries.')

if __name__=='__main__': main()
